// Prepara el aviso de error (HU-05): que flujo, que paso y que error.
//
// IMPORTANTE: el aviso no puede llevar credenciales. Antes de enviar nada se limpia
// cualquier cosa que parezca una clave (regla A7).
const e = $input.first().json ?? {};

// n8n mete el error dentro de 'execution' (execution.error) y el flujo que ha
// fallado en 'workflow' (workflow.name).
const err = e.execution?.error ?? e.error ?? {};
const flujo = e.workflow?.name ?? '(flujo desconocido)';
const nodo = err.node?.name ?? e.execution?.lastNodeExecuted ?? e.lastNodeExecuted ?? '(paso desconocido)';
const mensaje = err.message ?? e.message ?? 'Error desconocido';
const cuando = err.timestamp ?? e.execution?.startedAt ?? new Date().toISOString();

// Limpia secretos que se hayan colado en el mensaje de error.
const limpiar = (texto) => String(texto ?? '')
  .replace(/(x-api-key\s*[:=]\s*)\S+/gi, '$1***')
  .replace(/((?:api[_-]?key|apikey|password|passwd|secret|token|bearer)\s*[:=]\s*)\S+/gi, '$1***')
  .replace(/\bsk-[A-Za-z0-9_-]{8,}/g, 'sk-***')
  .replace(/\bey[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g, '***');

const cuerpo = [
  'Una automatizacion ha fallado:',
  '',
  'Flujo: ' + flujo,
  'Paso: ' + nodo,
  'Error: ' + limpiar(mensaje),
  'Cuando: ' + cuando,
  '',
  'Revisalo en n8n > Executions.',
].join('\n');

return [{
  json: {
    flujo,
    nodo,
    mensaje: limpiar(mensaje),
    cuerpo,
  },
}];

// El aviso va a la tienda. Si no se puede enviar, se deja constancia en el
// propio item para que la ejecucion de n8n lo muestre.
const aviso = $input.first().json ?? {};
const emailTienda = $vars.EMAIL_MARISA || 'marisa@pasofirme.example';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Error en una automatizacion · ' + (aviso.flujo ?? ''),
    cuerpo: aviso.cuerpo ?? '',
    cuerpo_html: '<p>' + escapar(aviso.cuerpo ?? '').replace(/\n/g, '<br>') + '</p>',
  },
}];
